// code.mjs — fenced and indented code block support for the zero-dependency
// Python-Markdown-compatible renderer.
//
// Pure module: no side effects, no shared state, no RegExp usage — all
// matching is done with explicit character scanning.

// ---------------------------------------------------------------------------
// Escaping (code / attribute context: & < > " are all escaped).
// Implemented locally so this module does not depend on text.mjs export
// names; semantics match the shared contract for code/attribute text.
// ---------------------------------------------------------------------------

export function escapeHtmlAll(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '&') out += '&amp;';
    else if (c === '<') out += '&lt;';
    else if (c === '>') out += '&gt;';
    else if (c === '"') out += '&quot;';
    else out += c;
  }
  return out;
}

const escapeAttr = escapeHtmlAll;

// ---------------------------------------------------------------------------
// Small scanning helpers
// ---------------------------------------------------------------------------

function isSpaceOrTab(c) {
  return c === ' ' || c === '\t';
}

function hasWhitespace(s) {
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === ' ' || c === '\t' || c === '\n' || c === '\r') return true;
  }
  return false;
}

function splitWhitespace(s) {
  const out = [];
  let i = 0;
  const n = s.length;
  while (i < n) {
    while (i < n && isSpaceOrTab(s[i])) i++;
    if (i >= n) break;
    let j = i;
    while (j < n && !isSpaceOrTab(s[j])) j++;
    out.push(s.slice(i, j));
    i = j;
  }
  return out;
}

function isIdentStart(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isIdentChar(c) {
  return isIdentStart(c) || (c >= '0' && c <= '9');
}

function isDigit(c) {
  return c >= '0' && c <= '9';
}

// ---------------------------------------------------------------------------
// parseFenceOpening(line)
//
// Recognizes a top-level (column 0) opening fence of >= 3 backticks or
// tildes, optionally followed by an info string:
//   ```            -> no language
//   ```python      -> bare language
//   ```.python     -> dotted language
//   ```{.python #id .cls key=val}
//
// The info string must consume the rest of the line (modulo surrounding
// whitespace); a bare language with extra words is NOT a fence (returns
// null), matching Python-Markdown's fenced_code behavior.
//
// Returns null when not a fence, otherwise:
//   { char, length, fence, lang, id, preClasses, info }
// where `lang` is the language for the <code> element (first .class wins,
// or bare language), `id`/`preClasses` belong on <pre>.
// ---------------------------------------------------------------------------

export function parseFenceOpening(line) {
  if (typeof line !== 'string' || line.length === 0) return null;
  const ch = line[0];
  if (ch !== '`' && ch !== '~') return null;

  const n = line.length;
  let i = 0;
  while (i < n && line[i] === ch) i++;
  if (i < 3) return null;
  const fence = line.slice(0, i);

  // Info string: rest of line, trimmed of surrounding spaces/tabs.
  let s = i;
  while (s < n && isSpaceOrTab(line[s])) s++;
  let e = n;
  while (e > s && isSpaceOrTab(line[e - 1])) e--;
  const info = line.slice(s, e);

  let lang = null;
  let id = null;
  const classes = [];

  if (info.length > 0) {
    if (info[0] === '{') {
      // Attribute list: must close at end of line.
      if (info[info.length - 1] !== '}') return null;
      const tokens = splitWhitespace(info.slice(1, -1));
      for (const tok of tokens) {
        if (tok.length === 0) continue;
        const t0 = tok[0];
        if (t0 === '.') {
          if (tok.length === 1) return null; // bare dot
          classes.push(tok.slice(1));
        } else if (t0 === '#') {
          if (tok.length === 1) return null; // bare hash
          id = tok.slice(1);
        } else {
          // key=value or bare key. Unknown keys are ignored; `lang=` is
          // honored as an explicit language.
          const eq = tok.indexOf('=');
          if (eq > 0) {
            const key = tok.slice(0, eq);
            let val = tok.slice(eq + 1);
            // Strip one layer of surrounding quotes if present.
            if (val.length >= 2) {
              const v0 = val[0];
              const v1 = val[val.length - 1];
              if ((v0 === '"' && v1 === '"') || (v0 === "'" && v1 === "'")) {
                val = val.slice(1, -1);
              }
            }
            if (key === 'lang' && val.length > 0 && lang === null) {
              lang = val;
            }
          }
          // bare words / unknown keys: silently ignored.
        }
      }
      // First .class becomes the code language; remaining classes go to <pre>.
      if (classes.length > 0) lang = classes[0];
    } else {
      // Bare language: must be a single word; extra bare words invalidate
      // the fence entirely (Python-Markdown falls back to a paragraph).
      if (hasWhitespace(info)) return null;
      // A backtick fence's info string may not contain backticks.
      if (ch === '`' && info.indexOf('`') !== -1) return null;
      lang = info[0] === '.' ? info.slice(1) : info;
      if (lang.length === 0) return null; // info was just "."
    }
  }

  return {
    char: ch,
    length: fence.length,
    fence,
    lang,
    id,
    preClasses: classes.length > 1 ? classes.slice(1) : [],
    info,
  };
}

// ---------------------------------------------------------------------------
// findFenceClose(lines, startIndex, fence)
//
// A closing line must be exactly the same fence character repeated the same
// number of times, plus optional trailing spaces/tabs — nothing else.
// `fence` may be the fence string ("```") or the object returned by
// parseFenceOpening. Returns the index of the closing line, or null.
// ---------------------------------------------------------------------------

export function findFenceClose(lines, startIndex, fence) {
  let ch;
  let len;
  if (typeof fence === 'string') {
    if (fence.length === 0) return null;
    ch = fence[0];
    len = fence.length;
  } else if (fence && typeof fence === 'object') {
    ch = fence.char;
    len = fence.length;
    if (typeof ch !== 'string' || typeof len !== 'number') return null;
  } else {
    return null;
  }

  for (let i = startIndex; i < lines.length; i++) {
    const line = lines[i];
    if (typeof line !== 'string') continue;
    let e = line.length;
    while (e > 0 && isSpaceOrTab(line[e - 1])) e--;
    if (e !== len) continue;
    let ok = true;
    for (let j = 0; j < e; j++) {
      if (line[j] !== ch) {
        ok = false;
        break;
      }
    }
    if (ok) return i;
  }
  return null;
}

// ---------------------------------------------------------------------------
// renderFencedCode(info, contentLines)
//
// info: object from parseFenceOpening (or { lang, id, preClasses } shape).
// contentLines: array of code lines without trailing newlines.
// Non-empty content gets a trailing "\n" appended before escaping; empty
// content does not. Output has no trailing newline:
//   <pre[ id=".." class=".."]><code[ class="language-x"]>..</code></pre>
// ---------------------------------------------------------------------------

export function renderFencedCode(info, contentLines) {
  const lang = info && info.lang ? info.lang : null;
  const id = info && info.id ? info.id : null;
  const preClasses =
    info && Array.isArray(info.preClasses) ? info.preClasses : [];

  let body = contentLines.join('\n');
  if (body !== '') body += '\n';
  body = escapeHtmlAll(body);

  let preAttrs = '';
  if (id !== null && id !== '') preAttrs += ' id="' + escapeAttr(id) + '"';
  if (preClasses.length > 0) {
    let cls = '';
    for (let k = 0; k < preClasses.length; k++) {
      if (k > 0) cls += ' ';
      cls += escapeAttr(preClasses[k]);
    }
    preAttrs += ' class="' + cls + '"';
  }

  const codeAttrs =
    lang !== null && lang !== ''
      ? ' class="language-' + escapeAttr(lang) + '"'
      : '';

  return '<pre' + preAttrs + '><code' + codeAttrs + '>' + body + '</code></pre>';
}

// ---------------------------------------------------------------------------
// Conservative Python highlighting approximation.
//
// Only used when the language is explicitly Python. Emits common Pygments
// span classes: k (keyword), kc (keyword constant), nf/nc (def/class name),
// w (whitespace between keyword and name), p (punctuation runs), s (string),
// c1 (comment), mi (number). Everything else is passed through escaped.
// Pure function: no side effects, inputs are not mutated.
// ---------------------------------------------------------------------------

const PY_KEYWORDS = new Set([
  'and', 'as', 'assert', 'async', 'await', 'break', 'class', 'continue',
  'def', 'del', 'elif', 'else', 'except', 'finally', 'for', 'from',
  'global', 'if', 'import', 'in', 'is', 'lambda', 'nonlocal', 'not', 'or',
  'pass', 'raise', 'return', 'try', 'while', 'with', 'yield',
]);

const PY_CONSTANTS = new Set(['True', 'False', 'None', 'Ellipsis', 'NotImplemented']);

function isPyPunct(c) {
  return (
    c === '(' || c === ')' || c === '[' || c === ']' || c === '{' ||
    c === '}' || c === ':' || c === ',' || c === '.' || c === ';' ||
    c === '@'
  );
}

function isPythonLang(lang) {
  if (typeof lang !== 'string') return false;
  const l = lang.toLowerCase();
  return l === 'python' || l === 'py' || l === 'python3' || l === 'py3';
}

function highlightPython(src) {
  let out = '';
  let i = 0;
  const n = src.length;
  // Set right after emitting `def`/`class` keyword: the next whitespace run
  // becomes a `w` span and the next identifier an `nf`/`nc` span.
  let pendingNameClass = null; // 'nf' | 'nc' | null

  while (i < n) {
    const c = src[i];

    // Comment: '#' to end of line.
    if (c === '#') {
      let j = i;
      while (j < n && src[j] !== '\n') j++;
      out += '<span class="c1">' + escapeHtmlAll(src.slice(i, j)) + '</span>';
      i = j;
      continue;
    }

    // String: single/double quoted, single-line, backslash escapes.
    if (c === '"' || c === "'") {
      let j = i + 1;
      while (j < n && src[j] !== c && src[j] !== '\n') {
        if (src[j] === '\\' && j + 1 < n) j += 2;
        else j++;
      }
      if (j < n && src[j] === c) j++;
      out += '<span class="s">' + escapeHtmlAll(src.slice(i, j)) + '</span>';
      i = j;
      continue;
    }

    // Identifier / keyword.
    if (isIdentStart(c)) {
      let j = i;
      while (j < n && isIdentChar(src[j])) j++;
      const word = src.slice(i, j);
      if (pendingNameClass !== null) {
        out += '<span class="' + pendingNameClass + '">' + escapeHtmlAll(word) + '</span>';
        pendingNameClass = null;
      } else if (PY_KEYWORDS.has(word)) {
        out += '<span class="k">' + word + '</span>';
        if (word === 'def') pendingNameClass = 'nf';
        else if (word === 'class') pendingNameClass = 'nc';
      } else if (PY_CONSTANTS.has(word)) {
        out += '<span class="kc">' + word + '</span>';
      } else {
        out += escapeHtmlAll(word);
      }
      i = j;
      continue;
    }

    // Number (simple integer / float run).
    if (isDigit(c)) {
      let j = i;
      while (j < n && (isIdentChar(src[j]) || src[j] === '.')) j++;
      out += '<span class="mi">' + escapeHtmlAll(src.slice(i, j)) + '</span>';
      i = j;
      continue;
    }

    // Punctuation run -> one `p` span (Pygments groups e.g. "():" together).
    if (isPyPunct(c)) {
      let j = i;
      while (j < n && isPyPunct(src[j])) j++;
      out += '<span class="p">' + escapeHtmlAll(src.slice(i, j)) + '</span>';
      i = j;
      continue;
    }

    // Whitespace: only wrapped in `w` between def/class and the name;
    // other whitespace (including indentation) stays plain.
    if (c === ' ' || c === '\t') {
      let j = i;
      while (j < n && (src[j] === ' ' || src[j] === '\t')) j++;
      if (pendingNameClass !== null) {
        out += '<span class="w">' + escapeHtmlAll(src.slice(i, j)) + '</span>';
      } else {
        out += src.slice(i, j);
      }
      i = j;
      continue;
    }

    // Anything else: pass through escaped.
    out += escapeHtmlAll(c);
    i++;
  }
  return out;
}

// ---------------------------------------------------------------------------
// renderIndentedCode(contentText, options = {})
//
// Default: <pre><code>..</code></pre> with the content escaped and a single
// trailing "\n" appended when non-empty and not already newline-terminated.
//
// options.codehilite === true:
//   <div class="codehilite"><pre><span></span><code>..</code></pre></div>
//   A first line of the form ":::lang" (optional leading/trailing
//   whitespace) is stripped and selects highlighting. Explicit Python gets a
//   conservative Pygments-style span approximation; any other language is
//   silently rendered as plain text (matching the observed executable).
// ---------------------------------------------------------------------------

function parseColonColonLang(line) {
  let s = 0;
  const n = line.length;
  while (s < n && isSpaceOrTab(line[s])) s++;
  if (line[s] !== ':' || line[s + 1] !== ':' || line[s + 2] !== ':') return null;
  let j = s + 3;
  const langStart = j;
  while (j < n && !isSpaceOrTab(line[j])) j++;
  const lang = line.slice(langStart, j);
  // Rest of the line must be whitespace only.
  while (j < n) {
    if (!isSpaceOrTab(line[j])) return null;
    j++;
  }
  return lang; // may be '' — line is still stripped, no highlighting.
}

export function renderIndentedCode(contentText, options = {}) {
  let text = typeof contentText === 'string' ? contentText : '';
  let lang = null;

  if (options && options.codehilite) {
    const nl = text.indexOf('\n');
    const first = nl === -1 ? text : text.slice(0, nl);
    const parsed = parseColonColonLang(first);
    if (parsed !== null) {
      lang = parsed === '' ? null : parsed;
      text = nl === -1 ? '' : text.slice(nl + 1);
    }
  }

  let body = text;
  if (body !== '' && body[body.length - 1] !== '\n') body += '\n';

  let inner;
  if (options && options.codehilite && isPythonLang(lang)) {
    inner = highlightPython(body);
  } else {
    inner = escapeHtmlAll(body);
  }

  if (options && options.codehilite) {
    return (
      '<div class="codehilite"><pre><span></span><code>' +
      inner +
      '</code></pre></div>'
    );
  }
  return '<pre><code>' + inner + '</code></pre>';
}

